<?= $this->section('main-content') ?><main class="dashboard-container" aria-labelledby="doctor-profile-title"><div class="page-heading"><div><div class="page-eyebrow">Doctor panel / account</div><h1 id="doctor-profile-title" class="h3 mb-1">Profile and settings</h1><div class="text-muted">Update contact details for your clinic profile.</div></div></div><div class="card"><div class="card-header"><h2 class="h5 mb-0">Professional profile</h2></div><form id="doctor-profile-form"><div class="card-body"><div class="form-row"><?= csrf_field() ?><?= view('templates/_telephone_contact', ['idPrefix' => 'doctor-profile', 'mobileName' => 'mobile', 'mobileId' => 'doctor-mobile', 'mobileValue' => $doctor['mobile'] ?? '', 'telephoneCodes' => $telephoneCodes ?? [], 'selectedId' => $doctor['telephone_country_code_id'] ?? 0, 'manualCode' => $doctor['telephone_country_code'] ?? '', 'countryName' => $doctor['telephone_country_name'] ?? '', 'manual' => empty($doctor['telephone_country_code_id']) && ! empty($doctor['telephone_country_code'])]) ?><div class="form-group col-md-6"><label for="doctor-email">Email</label><input id="doctor-email" class="form-control" type="email" name="email" value="<?= esc($doctor['email'] ?? '') ?>" maxlength="150"><div class="validation-error" id="emailErr"></div></div><div class="form-group col-12"><label for="doctor-address">Address</label><textarea id="doctor-address" class="form-control" name="address" maxlength="2000"><?= esc($doctor['address'] ?? '') ?></textarea><div class="validation-error" id="addressErr"></div></div></div></div><div class="card-footer text-right"><button class="btn btn-primary" type="submit">Save profile</button></div></form></div></main><?= $this->endSection() ?>
